window.docContents[44].resolve({"/Tactics/#Logical-Foundations--Tactics___-More-Basic-Tactics--The--apply--Tactic--Supplying-arguments-to--apply":{"contents":"This note is probably dead...AAA dislikes the ...with... variants of tactics, which he\nfeels don't work very well.  But we (Arthur and BCP) decided to\nleave things alone for now, since removing ...with... would\nrequire changing MANY proofs.\n\nThe following silly example uses two rewrites in a row to\nget from \\[a;b] to \\[e;f].\n\ntheorem trans_eq_example (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  rw [eq1, eq2]\ntheorem trans_eq_example (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  rw [eq1, eq2]\ntheorem trans_eq_example (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  rw [eq1, eq2]\n\n\n\n\nSince this is a common pattern, we might like to pull it out as a\nlemma that records, once and for all, the fact that equality is\ntransitive.\n\nHIDE: Robert Rand: I found using m, n and o throughout this discussion\nsuper confusing -- m doesn't come between n and o! Rocq's eq_trans uses\nx, y and z, which is what I wanted to change this too anyhow.\n\n\ntheorem trans_eq {α : Type} (x y z : α) :\n    x = y → y = z → x = z := by\n  intro eq1 eq2\n  rw [eq1, eq2]\ntheorem trans_eq {α : Type} (x y z : α) :\n    x = y → y = z → x = z := by\n  intro eq1 eq2\n  rw [eq1, eq2]\ntheorem trans_eq {α : Type} (x y z : α) :\n    x = y → y = z → x = z := by\n  intro eq1 eq2\n  rw [eq1, eq2]\n\n\nNowwe should be able to use trans_eq to prove the above\nexample.\n\nIs this still true?\n\nRobert Rand: This one makes a nice workinclass. You can show\nthe various ways around the problem, including named \"with\",\nunnamed \"with\", and (if you desire), explicitly providing the\narguments to trans_eq.\n\n\n\n\nBut doing apply trans_eq doesn't finish the proof!\n\ntheorem trans_eq_example' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq\n  sorry\n  sorry\n  sorry\ntheorem trans_eq_example' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq\n  sorry\n  sorry\n  sorry\ntheorem trans_eq_example' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq\n  sorry\n  sorry\n  sorry\n\n\n\n\nThis does:\n\ntheorem trans_eq_example'' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq [a, b] [c, d] [e, f] eq1 eq2\ntheorem trans_eq_example'' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq [a, b] [c, d] [e, f] eq1 eq2\ntheorem trans_eq_example'' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq [a, b] [c, d] [e, f] eq1 eq2\n\n\nThis and below are new (my addition), thoughts?\n\nIn the previous example, we had to specify the x and z arguments\nto trans_eq before we could supply [c, d] for y or eq1 and eq2 for\nthe premises. However, we just said that Lean was able to infer these arguments, so it's\na bit redundant (and wordy) for us to do it. Thankfully,\nLean allows us to use _s for positional arguments that it can infer.\n\ntheorem trans_eq_example''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq _ _ _ eq1 eq2\ntheorem trans_eq_example''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq _ _ _ eq1 eq2\ntheorem trans_eq_example''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq _ _ _ eq1 eq2\n\n\nAside: if we know the name of\nthe argument we are supplying (in this case y), we can\njust name it directly and avoid typing any _s.\n\ntheorem trans_eq_example'''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq (y := [c, d])\n  apply eq1\n  apply eq2\ntheorem trans_eq_example'''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq (y := [c, d])\n  apply eq1\n  apply eq2\ntheorem trans_eq_example'''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  apply trans_eq (y := [c, d])\n  apply eq1\n  apply eq2\n\n\n\n\nBy convention, we use exact for situations when we can completely finish the proof\nwith a single application\n\ntheorem trans_eq_example_exact (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  exact trans_eq _ _ _ eq1 eq2\ntheorem trans_eq_example_exact (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  exact trans_eq _ _ _ eq1 eq2\ntheorem trans_eq_example_exact (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  exact trans_eq _ _ _ eq1 eq2\n\n\nif we decide we want to introduce calc earlier, we can\nremove this explanation or tweak it.  BCP: I think we did introduce it earlier...\n\n\n\ncalc is also available as a tactic.\n\ntheorem trans_eq_example''''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  calc\n  [a, b] = [c, d] := by rw [eq1]\n  [c, d] = [e, f] := by rw [eq2]\ntheorem trans_eq_example''''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  calc\n  [a, b] = [c, d] := by rw [eq1]\n  [c, d] = [e, f] := by rw [eq2]\ntheorem trans_eq_example''''' (a b c d e f : Nat) :\n    [a, b] = [c, d] →\n    [c, d] = [e, f] →\n    [a, b] = [e, f] := by\n  intro eq1 eq2\n  calc\n  [a, b] = [c, d] := by rw [eq1]\n  [c, d] = [e, f] := by rw [eq2]\n\n\n\n\n","context":"Logical Foundations\u0009Tactics: More Basic Tactics\u0009The  apply  Tactic","header":"6.1.1. Supplying arguments to  apply","id":"/Tactics/#Logical-Foundations--Tactics___-More-Basic-Tactics--The--apply--Tactic--Supplying-arguments-to--apply"}});